func TestSessionStartContextPreToolRefusalAndStopBlocksAreRecorded(t *testing.T) {
	for _, name := range []string{"stops", "pretool-decisions"} {
		rec := loadRecording(t, name)
		for who, rollout := range map[string]string{"recorded": recordedRollout(t, rec), "mock": replay(t, rec).rollout(t)} {
			switch name {
			case "stops":
				assert.Equal(t, []string{"SS-CTX"}, addedContext(t, rollout), who)
				assert.True(t, resultTold(t, rollout, "DENY-REASON", "exit status"), who+": a JSON refusal")
				assert.True(t, resultTold(t, rollout, "PRE-BLOCK-MSG", "exit status"), who+": an exit 2 refusal")
				assert.Equal(t, 2, strings.Count(rollout, "<hook_prompt"), who+": each stop block")
				assert.Contains(t, rollout, "BLOCK-JSON-REASON", who)
				assert.Contains(t, rollout, "BLOCK-EXIT2-REASON", who)
			case "pretool-decisions":
				assert.True(t, resultTold(t, rollout, "Command blocked by PreToolUse hook: deny by hook deny", "exit status"), who)
			}
		}
	}
}

// The same holds for the other ways a hook decides, which the docs describe
// (hooks#userpromptsubmit): context by JSON
// additionalContext is a developer message; a PostToolUse block, by exit 2
// (runs/posttool-block) or by a JSON decision, is recorded as the call's result
// in place of the output; a UserPromptSubmit block, by exit 2
// (runs/prompt-blocked) or by a JSON decision, leaves no record of the prompt
// or of the reason.
// sr:proves hook-output-transcript-records/codex
func TestOtherHookDecisionsAreRecordedTheSameWay(t *testing.T) {
	post := loadRecording(t, "posttool-block")
	for name, rollout := range map[string]string{"recorded": recordedRollout(t, post), "mock": replay(t, post).rollout(t)} {
		assert.True(t, resultTold(t, rollout, "POST-FEEDBACK-MSG", "POSTBLOCK"), name+": the feedback replaces the output")
	}
	prompt := loadRecording(t, "prompt-blocked")
	for name, rollout := range map[string]string{"recorded": recordedRollout(t, prompt), "mock": replay(t, prompt).rollout(t)} {
		assert.NotContains(t, rollout, "PROMPT-BLOCK-MSG", name+": the reason of a blocked prompt was recorded")
		assert.NotContains(t, rollout, "SHOULDNOTRUN", name+": a blocked prompt was recorded")
	}

	byJSON := execMock(t, scenario{
		HooksJSON: hooksJSON("sh hook.sh", "UserPromptSubmit", "PostToolUse"),
		Files: map[string]string{"hook.sh": `in=$(cat); case "$in" in
  *UserPromptSubmit*) echo '{"hookSpecificOutput":{"hookEventName":"UserPromptSubmit","additionalContext":"CTX-PROMPT"}}' ;;
  *PostToolUse*) echo '{"decision":"block","reason":"POST-JSON-REASON"}' ;;
esac`},
		Script: callThenResult, Prompt: "go", Env: withCalls(t, "echo OUT"),
	})
	rollout := byJSON.rollout(t)
	assert.Equal(t, []string{"CTX-PROMPT"}, addedContext(t, rollout))
	assert.True(t, resultTold(t, rollout, "POST-JSON-REASON", "OUT"))

	blocked := execMock(t, scenario{
		HooksJSON: hooksJSON("sh hook.sh", "UserPromptSubmit"),
		Files:     map[string]string{"hook.sh": `echo '{"decision":"block","reason":"PROMPT-JSON-REASON"}'`},
		Script:    callThenResult, Prompt: "SECRET-PROMPT", Env: withCalls(t),
	})
	assert.NotContains(t, blocked.rollout(t), "PROMPT-JSON-REASON")
	assert.NotContains(t, blocked.rollout(t), "SECRET-PROMPT")
}
func (s *File) append(kind string, payload map[string]any) {
	enc := json.NewEncoder(s.f)
	enc.SetEscapeHTML(false)
	_ = enc.Encode(map[string]any{"timestamp": time.Now().UTC().Format(time.RFC3339Nano), "type": kind, "payload": payload})
}

func message(role, ctype, text string) map[string]any {
	return map[string]any{"type": "message", "role": role,
		"content": []map[string]string{{"type": ctype, "text": text}}}
}

// User records a user message: the prompt, or the text a hook sent in its place
// (the reason a stop hook blocks with). It is all a hook leaves of its own:
// nothing records a hook that succeeded silently, failed or timed out.
// sr:provides hook-output-transcript-records/codex
func (s *File) User(text string) { s.append("response_item", message("user", "input_text", text)) }

// Developer records context a hook added.
// sr:provides hook-output-transcript-records/codex
func (s *File) Developer(text string) {
	s.append("response_item", message("developer", "input_text", text))
}

// Assistant records a message from the agent.
func (s *File) Assistant(text string) {
	s.append("response_item", message("assistant", "output_text", text))
}

// ToolCall records a tool call the agent made.
func (s *File) ToolCall(callID, name string, input json.RawMessage) {
	s.append("response_item", map[string]any{"type": "function_call", "call_id": callID, "name": name, "arguments": string(input)})
}

// ToolOutput records what the agent was told a tool call returned.
